import sys

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    pattern = data[1] if len(data) > 1 else ""

    candidates = []
    if n == 6:
        candidates = ["espeon"]
    elif n == 7:
        candidates = ["jolteon", "flareon", "umbreon", "leafeon", "glaceon", "sylveon"]
    elif n == 8:
        candidates = ["vaporeon"]

    for cand in candidates:
        match = True
        for i, ch in enumerate(pattern):
            if ch != "." and ch != cand[i]:
                match = False
                break
        if match:
            print(cand)
            return

if __name__ == "__main__":
    solve()
"}

