import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    commands = data[1] if len(data) > 1 else ""

    answer = 0

    # Check all substrings
    for start in range(n):
        vertical_balance = 0
        horizontal_balance = 0

        for end in range(start, n):
            cmd = commands[end]
            if cmd == 'U':
                vertical_balance += 1
            elif cmd == 'D':
                vertical_balance -= 1
            elif cmd == 'R':
                horizontal_balance += 1
            elif cmd == 'L':
                horizontal_balance -= 1

            # Check if we're back to the starting position
            if vertical_balance == 0 and horizontal_balance == 0:
                answer += 1

    print(answer)

if __name__ == "__main__":
    solve()
"}

