def count_palindromic_pairs(s):
    n = len(s)
    palindromes = []

    # Find all palindromic substrings with their start and end indices
    for i in range(n):
        # Odd length
        l, r = i, i
        while l >= 0 and r < n and s[l] == s[r]:
            palindromes.append((l + 1, r + 1))  # 1-indexed
            l -= 1
            r += 1

    for i in range(n - 1):
        # Even length
        l, r = i, i + 1
        while l >= 0 and r < n and s[l] == s[r]:
            palindromes.append((l + 1, r + 1))  # 1-indexed
            l -= 1
            r += 1

    # Count pairs
    count = 0
    for start1, end1 in palindromes:
        # Count palindromes that start after end1
        for start2, end2 in palindromes:
            if start2 > end1:
                count += 1

    return count

s = input().strip()
print(count_palindromic_pairs(s))
"}

