def solve():
    data = list(map(int, input().split()))
    n, k, q = data[0], data[1], data[2]

    # Count how many recipes cover each temperature
    count = [0] * 200001

    for _ in range(n):
        l, r = map(int, input().split())
        count[l] += 1
        count[r + 1] -= 1

    # Convert to prefix sum to get counts for each temperature
    for i in range(1, 200001):
        count[i] += count[i - 1]

    # Create prefix sum of admissible temperatures
    admissible = [0] * 200001
    for i in range(1, 200001):
        if count[i] >= k:
            admissible[i] = 1

    for i in range(1, 200001):
        admissible[i] += admissible[i - 1]

    for _ in range(q):
        a, b = map(int, input().split())
        print(admissible[b] - admissible[a - 1])

solve()
"}

