n = int(input())

dominoes = []
for _ in range(n):
    xi, yi = map(int, input().split())
    dominoes.append((xi % 2, yi % 2))

total_upper = sum(x for x, y in dominoes)
total_lower = sum(y for x, y in dominoes)

total_upper_parity = total_upper % 2
total_lower_parity = total_lower % 2

# Total sum parity must be even for both sums to be even
if (total_upper_parity + total_lower_parity) % 2 == 1:
    print(-1)
else:
    # Count dominoes with different parities (0,1) or (1,0)
    diff_parity_count = sum(1 for x, y in dominoes if x != y)

    if total_upper_parity == 0 and total_lower_parity == 0:
        print(0)
    elif diff_parity_count >= 1:
        print(1)
    else:
        print(-1)
"}

