def solve():
    n = int(input())

    juices = []
    for _ in range(n):
        c, s = input().split()
        c = int(c)
        juices.append((c, set(s)))

    # One juice with all three vitamins
    min_abc = min(c for c, vitamins in juices if 'A' in vitamins and 'B' in vitamins and 'C' in vitamins)

    # Two juices
    min_two = float('inf')
    for i in range(n):
        for j in range(i, n):
            c1, v1 = juices[i]
            c2, v2 = juices[j]
            if v1.union(v2) == {'A', 'B', 'C'}:
                min_two = min(min_two, c1 + c2)

    # Three juices
    min_three = float('inf')
    for i in range(n):
        for j in range(i, n):
            for k in range(j, n):
                c1, v1 = juices[i]
                c2, v2 = juices[j]
                c3, v3 = juices[k]
                if v1.union(v2).union(v3) == {'A', 'B', 'C'}:
                    min_three = min(min_three, c1 + c2 + c3)

    result = min(min_abc, min_two, min_three)

    if result == float('inf'):
        print(-1)
    else:
        print(result)

solve()
