n = int(input())
juices = {}

# Read all juices and track minimum prices for each vitamin combination
for _ in range(n):
    price, vitamins = input().split()
    price = int(price)
    vitamins = set(vitamins)

    # Store the minimum price for this vitamin combination
    key = tuple(sorted(vitamins))
    if key not in juices or price < juices[key]:
        juices[key] = price

# Try all combinations
min_total = float('inf')

# Try 1 juice with all three vitamins
if ('A', 'B', 'C') in juices:
    min_total = juices[('A', 'B', 'C')]

# Try 2 juices: one with two vitamins, one with the third
# First find all juice combinations with two vitamins
juice_two = {k: v for k, v in juices.items() if len(k) == 2}
juice_one = {k: v for k, v in juices.items() if len(k) == 1}

for two_vitamins, cost_two in juice_two.items():
    for single_vitamin, cost_one in juice_one.items():
        # Check if they cover all three vitamins together
        if not (two_vitamins & single_vitamin):
