import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    dp = [float('inf')] * 8
    dp[0] = 0
    idx = 1
    for _ in range(n):
        c = int(data[idx])
        s = data[idx + 1]
        idx += 2
        mask = 0
        if 'A' in s:
            mask |= 1
        if 'B' in s:
            mask |= 2
        if 'C' in s:
            mask |= 4
        # Update dp
        for mask_i in range(8):
            if dp[mask_i] < float('inf'):
                new_mask = mask_i | mask
                if dp[new_mask] > dp[mask_i] + c:
                    dp[new_mask] = dp[mask_i] + c
    res = dp[7]
    if res == float('inf'):
        print(-1)
    else:
        print(res)

if __name__ == "__main__":
    solve()
"}

