import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    b = list(map(int, data[1:1+n]))

    # Count even and odd numbers
    even_count = 0
    odd_count = 0
    for num in b:
        if num % 2 == 0:
            even_count += 1
        else:
            odd_count += 1

    # Decide which set to remove
    if even_count <= odd_count:
        # Remove all even numbers
        removed = [num for num in b if num % 2 == 0]
    else:
        # Remove all odd numbers
        removed = [num for num in b if num % 2 != 0]

    print(len(removed))
    if removed:
        print(' '.join(map(str, removed)))

if __name__ == '__main__':
    solve()
"}

