n, k, M = map(int, input().split())
t = list(map(int, input().split()))

# Time to solve one complete task (all subtasks)
complete_time = sum(t)
# Points for one complete task
complete_points = k + 1

# Time to solve all n subtasks of type i
extra_times = [n * t[i] for i in range(k)]
# Points for solving all n subtasks of type i
extra_points = [n] * k

# Try different numbers of complete tasks
max_points = 0

for x in range(M // complete_time + 1):
    time_used = x * complete_time
    points = x * complete_points
    remaining_time = M - time_used

    # Solve as many extra subtasks as possible with remaining time
    # Strategy: solve the cheapest subtasks first

    # Sort t (0-indexed) by time (smallest first)
    sorted_t = sorted(t)

    # Try solving up to k subtasks (but limited by remaining time)
    for i in range(len(sorted_t)):
        if remaining_time >= sorted_t[i]:
            points += 1
            remaining_time -= sorted_t[i]
        else:
            break

    max_points = max(max_points, points)

# Also consider solving all subtasks of one type completely
# Or some combination

# Try solving all n subtasks of type i, then extra subtasks
for i in range(k):
    time_used = extra_times[i]
    if time_used <= M:
        points = extra_points[i]
        remaining_time = M - time_used

        # Solve as many extra subtasks as possible
        for j in range(len(sorted_t)):
            if remaining_time >= sorted_t[j]:
                points += 1
                remaining_time -= sorted_t[j]
            else:
                break

        max_points = max(max_points, points)

# Try solving a combination of different subtask types
# Try combinations of 1, 2, 3, ... subtask types
for m in range(1, k + 1):
    for i in range(k):
        for j in range(i + 1, k):
            for l in range(j + 1, k):
                if m == 1:
                    # One type
                    time_used = extra_times[i]
                    if time_used <= M:
                        points = extra_points[i]
                        remaining_time = M - time_used
                        for n in range(len(sorted_t)):
