                    # Two types
                    time_used = extra_times[i] + extra_times[j]
                    if time_used <= M:
                        points = extra_points[i] + extra_points[j]
                        remaining_time = M - time_used
                        for n in range(len(sorted_t)):
                            if remaining_time >= sorted_t[n]:
                                points += 1
                                remaining_time -= sorted_t[n]
                            else:
                                break
                        max_points = max(max_points, points)
                elif m == 3:
                    # Three types
                    time_used = extra_times[i] + extra_times[j] + extra_times[l]
                    if time_used <= M:
                        points = extra_points[i] + extra_points[j] + extra_points[l]
