            for curr in 'abcdefghijklmnopqrstuvwxyz':
                if curr == s[i]:
                    continue
                if j - 1 < 0:
                    continue
                dp[i][j][curr] = max(dp[i][j][curr], dp[i-1][j-1][prev] + bonus.get((prev, curr), 0))

