import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    data = [int(x) for x in data]
    n = data[0]
    m = data[1]
    grid = data[2:2 + n * m]

    # dp[i][j] = sum from (1,1) to (i,j) in down-right path
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            dp[i][j] = dp[i - 1][j] + dp[i][j - 1] - dp[i - 1][j - 1] + grid[(i - 1) * m + (j - 1)]

    # dp2[i][j] = sum from (n,1) to (i,j) in up-right path
    dp2 = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n, 0, -1):
        for j in range(1, m + 1):
            dp2[i][j] = dp2[i + 1][j] + dp2[i][j - 1] - dp2[i + 1][j - 1] + grid[(i - 1) * m + (j - 1)]

    total = dp[n][m] + dp2[1][m]
    min_val = min(grid)

    print(total - 2 * min_val)

if __name__ == "__main__":
    solve()
"}

