    found = False
    for i, (l, r) in enumerate(segments):
        intersects_all = True
        for j, (l2, r2) in enumerate(segments):
            if i == j:
                continue
            if l > r2 or r < l2:
                intersects_all = False
                break
        if intersects_all:
            found = True
            break

    if found:
        print(0)
    else:
        # Find the segment that needs least deletions
        min_deletions = n
        for i, (l, r) in enumerate(segments):
            # Segments that need to be deleted
            deletions = 0
            for j, (l2, r2) in enumerate(segments):
                if i == j:
                    continue
                # Delete if [l, r] does not intersect [l2, r2]
                if l > r2 or r < l2:
                    deletions += 1
            min_deletions = min(min_deletions, deletions)

        # We need to delete (n - min_deletions) segments
        # Because we keep min_deletions segments
        print(n - min_deletions)
