MOD = 1000000009

n, w, b = map(int, input().split())

# Precompute factorials up to max(n, w, b)
max_val = max(n, w, b)
fact = [1] * (max_val + 1)
for i in range(1, max_val + 1):
    fact[i] = fact[i-1] * i % MOD

def comb(n, k):
    """Number of ways to choose k elements from n"""
    if n < 0 or k < 0 or k > n:
        return 0
    return fact[n] * pow(fact[k] * fact[n - k] % MOD, MOD - 2, MOD) % MOD

def perm(n, k):
    """Number of ways to arrange k elements out of n (n! / (n - k)!)"""
    if n < 0 or k < 0 or k > n:
        return 0
    return fact[n] * pow(fact[n - k], MOD - 2, MOD) % MOD

result = 0
for k in range(1, n - 1):
    for m in range(1, n - k):
        if n - k - m >= 1:
            if w >= k and b >= m and w - k >= n - k - m:
                # C(n, k) * C(n-k, m) * P(w, k) * P(b, m) * P(w-k, n-k-m)
                c1 = comb(n, k)
                c2 = comb(n - k, m)
                p1 = perm(w, k)
                p2 = perm(b, m)
                p3 = perm(w - k, n - k - m)
                result = (result + c1 * c2 % MOD * p1 % MOD * p2 % MOD * p3) % MOD

print(result)
