def count_swallows(n, K, a):
    # Sort bacteria by size
    a.sort()

    # Count how many bacteria of each size
    count = {}
    for size in a:
        if size in count:
            count[size] += 1
        else:
            count[size] = 1

    # Start from the largest size and work backwards
    current_size = max(a)
    remaining_sizes = sorted(count.keys(), reverse=True)

    # We'll keep track of the current largest bacteria
    # This could swallow some smaller ones
    swallowable = []

    while remaining_sizes:
        # Current largest bacteria
        if remaining_sizes[0] < current_size:
            # This bacteria could potentially be swallowed
            if current_size - remaining_sizes[0] <= K:
                # It can be swallowed by current_size
                swallowable.append(remaining_sizes[0])
                remaining_sizes.pop(0)
                continue
            else:
                # It can't be swallowed, so it becomes new current
                current_size = remaining_sizes[0]
                remaining_sizes.pop(0)
        else:
            # It's smaller or equal, can't be swallowed
            remaining_sizes.pop(0)

    return n - len(swallowable)

