def solve():
    import sys
    data = sys.stdin.read().split()
    idx = 0

    t = int(data[idx])
    idx += 1

    results = []

    for _ in range(t):
        n, x, y = int(data[idx]), int(data[idx+1]), int(data[idx+2])
        idx += 3

        b = list(map(int, data[idx:idx+n]))
        idx += n

        # Count occurrences of each color in Bob's guess
        from collections import defaultdict
        cnt = defaultdict(int)
        for c in b:
            cnt[c] += 1

        a = [0] * n

        # Place exact matches first
        for i in range(x):
            a[i] = b[i]
            cnt[b[i]] -= 1
            if cnt[b[i]] == 0:
                del cnt[b[i]]

        # For the remaining positions, we need to place colors that are in Bob's guess
        # but we need to ensure we have enough matches
        for i in range(x, n):
            if cnt:
                # Use any remaining color
                for color in cnt:
                    if cnt[color] > 0:
                        a[i] = color
                        cnt[color] -= 1
                        if cnt[color] == 0:
                            del cnt[color]
                        break
            else:
                # No more colors left, just use any color
                a[i] = 1

        # Now check how many matches we have
        matches = 0
        for i in range(n):
            if a[i] == b[i]:
                matches += 1

        if matches == y:
            results.append("YES")
            results.append(' '.join(map(str, a)))
        else:
            results.append("NO")

    sys.stdout.write("\n".join(results))

