import sys

def parse_line(line):
    line = line.strip()
    if not line:
        return (None, None, None)

    if line.startswith("try"): return ("try", None, None)
    elif line.startswith("catch"):
        # Format: catch ( <type>, "<message>" )
        # Extract type and message
        content_start = line.find('(') + 1
        content_end = line.rfind(')')
        if content_start > content_end:
            return (None, None, None)

        content = line[content_start:content_end]
        if ',' not in content:
            return (None, None, None)

        type_part = content.split(',', 1)[0].strip()
        message_part = content.split(',', 1)[1].strip()
        message = message_part.strip('"') if message_part.startswith('"') else message_part
        return ("catch", type_part, message)
    elif line.startswith("throw"):
        # Format: throw ( <type> )
        content_start = line.find('(') + 1
        content_end = line.rfind(')')
        if content_start > content_end:
            return (None, None, None)

        content = line[content_start:content_end].strip()
        return ("throw", content, None)
    return (None, None, None)


def main():
    lines = sys.stdin.read().splitlines()
    n = int(lines[0])

    # Parse all lines and collect information
    try_stack = []  # stack of (line_idx, type, message)
    catch_positions = []  # list of (line_idx, type, message)
    throw_pos = -1
    throw_type = None

    for i in range(1, n + 1):
        line = lines[i]
        if not line:
            continue

        op, t, m = parse_line(line)
        if op == "try":
            try_stack.append((i, t, m))
        elif op == "catch":
            catch_positions.append((i, t, m))
        elif op == "throw":
            throw_pos = i
            throw_type = t

    # Now find matching try-catch pairs
    # Try to match catches with the most recent try
    catch_with_try = []

    # We need to iterate through all lines again to find matching pairs
    for i in range(1, n + 1):
        line = lines[i]
        if not line:
            continue

        op, t, m = parse_line(line)
        if op == "catch":
            if try_stack:
                try_line, try_type, try_message = try_stack.pop()
                catch_with_try.append((catch_positions[len(catch_with_try)], try_line, i))

    # Now find the appropriate catch for the throw
    result = "Unhandled Exception"

    # For each try-catch pair, check if throw occurred between them
    for catch_line, try_line, catch_line in catch_with_try:
        if try_line < throw_pos < catch_line:
            if throw_type == catch_line[1]:
                # This catch could handle the throw
                result = catch_line[2]
                break

    print(result)

if __name__ == "__main__":
    main()
