def solve():
    import sys
    data = sys.stdin.read().split()
    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        m = int(next(it))
        k = int(next(it))
        a = [int(next(it)) for _ in range(n)]

        # Define DP: dp[left][right][people][controlled] = guaranteed minimum
        # people: number of people before me
        # controlled: number of those people I've controlled

        # Base case: if people == 0, we can choose either left or right
        dp = [[[[0 for _ in range(m)] for _ in range(m)] for _ in range(m)] for _ in range(m)]

        for left in range(n):
            for right in range(n):
                for people in range(m):
                    for controlled in range(people):
                        # If no people left, we can choose either
                        if people == 0:
                            dp[left][right][people][controlled] = max(a[left], a[right])


        # Fill DP
        for people in range(1, m):
            for left in range(n):
                for right in range(n):
                    # If people = 0, already done
                    if left == right:
                        continue

                    # Option 1: not control this person (they will minimize our outcome)
                    # They can choose left or right, and we take min of the outcomes
                    # We need to decide whether to control or not

                    # If we control this person, we can choose the option that maximizes our outcome
                    val_control = -1
                    if people <= k:
                        val_control = max(
                            dp[left+1][right][people-1][people-1] if left+1 <= right else 0,
                            dp[left][right-1][people-1][people-1] if left <= right-1 else 0
                        )

                    val_not_control = -1
                    if people <= k:
                        val_not_control = min(
                            dp[left+1][right][people-1][people] if left+1 <= right else 0,
                            dp[left][right-1][people-1][people] if left <= right-1 else 0
                        )

                    # Choose the best option (if we can control)
                    best = val_control if val_control > val_not_control else val_not_control
                    dp[left][right][people][controlled] = best

        # Answer is dp[0][n-1][m-1][0]
        print(dp[0][n-1][m-1][0])

solve()
