import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Count occurrences of each cycle size
    freq = {}

    # Calculate Grundy numbers for each test
    result = []
    for size in a:
        # Calculate Grundy number
        # A cycle of size 1 has Grundy number 0
        # A cycle of size n has Grundy number equal to the number of 1s in binary representation
        if size == 1:
            g = 0
