import sys

def solve(s):
    n = len(s)
    result = list(s)

    # We want to maximize zeroes while preserving LNS properties
    # We can change s[i] from '1' to '0' if count_ones_after[i] >= count_ones_before[i]

    count_ones_before = [0] * n
    count_ones_after = [0] * n

    # Count number of '1's before each position
    ones_count = 0
    for i in range(n):
        count_ones_before[i] = ones_count
        if s[i] == '1':
            ones_count += 1

    # Count number of '1's after each position
    ones_count = 0
    for i in range(n - 1, -1, -1):
        count_ones_after[i] = ones_count
        if s[i] == '1':
            ones_count += 1

    # Try to set as many '1's to '0's as possible
    for i in range(n):
        if result[i] == '0':
            continue

        if count_ones_after[i] >= count_ones_before[i]:
            result[i] = '0'

    return ''.join(result)

if __name__ == '__main__':
    s = sys.stdin.readline().strip()
    print(solve(s))
