import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []

    for _ in range(t):
        n = int(next(it))
        a = [int(next(it)) for _ in range(n)]
        total_xor = 0
        for num in a:
            total_xor ^= num

        if total_xor == 0:
            out_lines.append("DRAW")
        else:
            if 0 in a:
                out_lines.append("LOSE")
            else:
                if n % 2 == 1:
                    out_lines.append("WIN")
                else:
                    out_lines.append("LOSE")

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
