import sys
from collections import defaultdict

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    r, s, p = map(int, data)

    # Memoization dictionary for DP
    memo = {}

    def dp(r, s, p):
        if (r, s, p) in memo:
            return memo[(r, s, p)]

        # Base cases: only one species survives
        if r > 0 and s == 0 and p == 0:
            return (1.0, 0.0, 0.0)
        if s > 0 and r == 0 and p == 0:
            return (0.0, 1.0, 0.0)
        if p > 0 and r == 0 and s == 0:
            return (0.0, 0.0, 1.0)

        # If all three species exist, compute transitions
        if r > 0 and s > 0 and p > 0:
            # Transition probabilities
            total = r * s + s * p + p * r
            prob_rs = r * s / total * 0.5
            prob_sp = s * p / total * 0.5
            prob_pr = p * r / total * 0.5

            # Probability of transitioning to (r-1, s, p)
            prob_r_1_s = r * s / (r + s + p) / (r + s + p - 1) * 0.5
            # Probability of transitioning to (r, s-1, p)
            prob_r_s_1 = r * s / (r + s + p) / (r + s + p - 1) * 0.5
            # Probability of transitioning to (r, s, p-1)
            prob_r_s_p_1 = s * p / (r + s + p) / (r + s + p - 1) * 0.5

            # Recursively compute probabilities
            prob_r_1_s_case = dp(r - 1, s, p)
            prob_r_s_1_case = dp(r, s - 1, p)
            prob_r_s_p_1_case = dp(r, s, p - 1)

            # Weighted average based on transition probabilities
            result = (
                prob_r_1_s_case[0] * prob_r_1_s + prob_r_s_1_case[0] * prob_r_s_1 + prob_r_s_p_1_case[0] * prob_r_s_p_1,
                prob_r_1_s_case[1] * prob_r_1_s + prob_r_s_1_case[1] * prob_r_s_1 + prob_r_s_p_1_case[1] * prob_r_s_p_1,
                prob_r_1_s_case[2] * prob_r_1_s + prob_r_s_1_case[2] * prob_r_s_1 + prob_r_s_p_1_case[2] * prob_r_s_p_1
            )
            memo[(r, s, p)] = result
