                if not increasing_pairs and decreasing_pairs:
                    expected = dp[to_tuple(new_p)]
                elif increasing_pairs and not decreasing_pairs:
                    expected = dp[to_tuple(new_p)]
                else:
                    # Random from increasing
                    expected_increasing = sum(dp[to_tuple(new_p2)] for new_p2 in increasing_swaps(new_p)) / len(increasing_pairs)
                    # Random from decreasing
                    expected_decreasing = sum(dp[to_tuple(new_p2)] for new_p2 in decreasing_swaps(new_p)) / len(decreasing_pairs)
                    expected = 0.5 * expected_increasing + 0.5 * expected_decreasing

            dp[to_tuple(p)] = 1.0 + expected
            best = min(best, dp[to_tuple(p)])

        return dp[to_tuple(p)]

