def solve():
    import sys
    input = sys.stdin.read().strip().split()
    if not input:
        return

    T = int(input[0])
    results = []

    for i in range(1, T + 1):
        N = int(input[i])
        res = 0

        while N > 1:
            if N % 2 == 1:
                # N is odd, must take 1 coin
                res += 1
                N -= 1
            else:
                # N is even, decide whether to take 1 or half
                half = N // 2
                if half % 2 == 1:
                    # Half is odd, take half coins
                    res += half
                    N = 1
                else:
                    # Half is even, take 1 coin
                    res += 1
                    N -= 1

        results.append(res)

    sys.stdout.write("\n".join(map(str, results)))

if __name__ == "__main__":
    solve()
