{"code": "from itertools import combinations

def solve_fencing_problem():
    n, q = map(int, input().split())
    painters = []
    for _ in range(q):
        l, r = map(int, input().split())
        painters.append((l, r))

    max_painted = 0

    # Consider all possible pairs of painters to exclude
    # This is the same as choosing q-2 painters to include
    for exclude1 in range(q):
        for exclude2 in range(exclude1 + 1, q):
            # Build the set of painted sections using all painters except exclude1 and exclude2
            painted = set()
            for i in range(q):
                if i != exclude1 and i != exclude2:
                    l, r = painters[i]
                    painted.update(range(l, r + 1))
            max_painted = max(max_painted, len(painted))

    print(max_painted)

solve_fencing_problem()
