def are_friends(a, b):
    """Check if a and b are friends"""
    if a == b:
        return False
    d = math.gcd(a, b)
    x = a // d
    y = b // d
    # Check if d, x, y form a triangle
    # Three sides: d, x, y
    sides = sorted([d, x, y])
    return sides[0] + sides[1] > sides[2]

def is_lonely(n):
    """Check if number n is lonely in the group 1..n"""
    for b in range(1, n + 1):
        if a == b:
            continue
        if are_friends(n, b):
            return False
    return True

import sys
import math

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    t = int(data[0])
    results = []

    for i in range(1, t + 1):
        n = int(data[i])
        count = 0
        for a in range(1, n + 1):
            if is_lonely(a):
                count += 1
        results.append(str(count))

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    main()
