n = int(input())

if n == 2:
    print('1')
elif n == 3:
    print('7')
else:
    # For n > 3, we want to maximize the number
    # We should try to use digit 7 as much as possible first, then digit 1s
    # But we need to be careful about the order (largest digit on the left)

    # Let's use a recursive approach that tries both possibilities
    # max_number_with_sections(n) = max('7' + max_number_with_sections(n-3), '1' + max_number_with_sections(n-2))
    # But we need to handle the base cases carefully

    def max_number_with_sections(n):
        if n == 2:
            return '1'
        elif n == 3:
            return '7'
        else:
            # Try both options
            option1 = '7' + max_number_with_sections(n - 3)
            option2 = '1' + max_number_with_sections(n - 2)

            # Choose the better option
            if int(option1) > int(option2):
                return option1
            else:
                return option2

    result = max_number_with_sections(n)
    print(result)
