import sys

def parse_line(line):
    # Remove whitespace and parse
    line = line.strip()
    if line.startswith('try'):
        return ('try', '')
    elif line.startswith('catch'):
        # Extract exception type and message
        line = line.replace('catch', '', 1).strip()
        # Split by comma
        parts = line.split(',')

        # Extract exception type
        exception_type_part = parts[0].strip()
        exception_type = exception_type_part[1:-1]  # Remove quotes

        # Extract message
        message_part = parts[1].strip()
        message = message_part[1:-1]  # Remove quotes

        return ('catch', exception_type, message)
    elif line.startswith('throw'):
        line = line.replace('throw', '', 1).strip()
        line = line[1:-1]  # Remove parentheses
        return ('throw', line)
    else:
        return None


def solve():
    n = int(sys.stdin.readline())

    stack = []
    throw_line = None
    throw_type = None

    for i in range(n):
        line = sys.stdin.readline()
        token = parse_line(line)

        if token is None:
            continue

        if token[0] == 'try':
            stack.append(('try', i))
        elif token[0] == 'catch':
            block_type, exception_type, message = token
            # Pop the last try block
            if stack:
                try_line, try_idx = stack.pop()
                # Store this catch block
                catch_blocks.append((try_idx, exception_type, message, i))
        elif token[0] == 'throw':
            throw_type = token[1]
            throw_line = i

    # Find matching catch block
    matching_catch = None

    for try_idx, exception_type, message, catch_idx in catch_blocks:
        if try_idx < throw_line and catch_idx > throw_line and exception_type == throw_type:
            if matching_catch is None or catch_idx < matching_catch[3]:
                matching_catch = (try_idx, exception_type, message, catch_idx)

    if matching_catch:
        print(matching_catch[2])
    else:
        print("Unhandled Exception")

if __name__ == "__main__":
    catch_blocks = []
    solve()
"}

