# Count pairs of non-overlapping palindromic substrings

def is_palindrome(s, l, r):
    """Check if substring from l to r (inclusive) is a palindrome"""
    while l < r:
        if s[l] != s[r]:
            return False
        l += 1
        r -= 1
    return True

s = input().strip()
length = len(s)

# Find all palindromic substrings
palindromes = []

# Expand around center
for center in range(2 * length - 1):
    # odd length palindrome
    l = center // 2
    r = l
    if center % 2 == 1:
        r += 1
    while l >= 0 and r < length:
        if s[l] == s[r]:
            palindromes.append((l, r))
            l -= 1
            r += 1
        else:
            break

# Now count pairs (i, j) where i ends before j starts
count = 0
for i in range(len(palindromes)):
    for j in range(i + 1, len(palindromes)):
        a1, b1 = palindromes[i]
        a2, b2 = palindromes[j]
        if b1 < a2:
            count += 1

print(count)
"}

