def count_palindrome_pairs(s):
    n = len(s)
    palindromes = []

    # Find all palindromic substrings
    # Odd-length palindromes (centered at each position)
    for i in range(n):
        l, r = i, i
        while l >= 0 and r < n and s[l] == s[r]:
            palindromes.append((l, r))
            l -= 1
            r += 1

    # Even-length palindromes (centered between each pair of positions)
    for i in range(n - 1):
        l, r = i, i + 1
        while l >= 0 and r < n and s[l] == s[r]:
            palindromes.append((l, r))
            l -= 1
            r += 1

    # Count non-overlapping pairs
    count = 0
    for i in range(len(palindromes)):
        for j in range(len(palindromes)):
            if i == j:
                continue
            l1, r1 = palindromes[i]
            l2, r2 = palindromes[j]
            if r1 < l2:
                count += 1

    return count

s = input().strip()
print(count_palindrome_pairs(s))
