def min_layers(N):
    """Return the minimal number of layers required for segments from 0 to N"""

    # Create all segments
    segments = []
    for a in range(N + 1):
        for b in range(a, N + 1):
            segments.append((a, b))

    # Try to assign segments to layers greedily
    layers = []
    for seg in segments:
        # Check if this segment can go in any existing layer
        placed = False
        for layer in layers:
            # Check if this segment overlaps with any segment in the layer
            overlap = False
            for other_seg in layer:
                # Segments overlap if they have an overlapping interior
                # They can share endpoints but not overlap
                a1, b1 = seg
                a2, b2 = other_seg
                if b1 > a2 and b2 > a1:
                    overlap = True
                    break
            if not overlap:
                layer.append(seg)
                placed = True
                break
        if not placed:
            layers.append([seg])

    return len(layers)

