n = int(input())
permutation = list(map(int, input().split()))

# Check if there are any fixed points in the given permutation
has_fixed = False
for i in range(n):
    if permutation[i] != -1 and permutation[i] == i + 1:
        has_fixed = True
        break

if has_fixed:
    print(0)
else:
    # Collect used numbers from non--1 positions
    used_numbers = set()
    for i in range(n):
        if permutation[i] != -1:
            used_numbers.add(permutation[i])

    # Get the numbers that need to be placed in -1 positions
    remaining_numbers = []
    for i in range(1, n + 1):
        if i not in used_numbers:
            remaining_numbers.append(i)

    m = len(remaining_numbers)
    # For each -1 position, we can't place the number equal to its position index
    # Count the number of ways to assign these numbers to positions

    # This is a derangement problem: m items, m positions, item i can't go to position i
    # But wait, the remaining numbers might not be exactly {1, 2, ..., m}

    # We need to count derangements of m items to m positions where:
    # - Item k (which is the k-th smallest remaining number) can't go to position k (1-indexed)

    # Formula: D = m! * (1 - 1/1! + 1/2! - 1/3! + ... + (-1)^m / m!)

    # Precompute factorials and inverse factorials
    MOD = 1000000007
    fact = [1] * (m + 1)
    for i in range(1, m + 1):
        fact[i] = fact[i - 1] * i % MOD

    inv_fact = [1] * (m + 1)
    inv_fact[m] = pow(fact[m], MOD - 2, MOD)
    for i in range(m - 1, -1, -1):
        inv_fact[i] = inv_fact[i + 1] * (i + 1) % MOD

    # Compute derangements
    D = 0
    for i in range(m + 1):
        if i % 2 == 0:
            D = (D + fact[m] * inv_fact[i]) % MOD
        else:
            D = (D - fact[m] * inv_fact[i]) % MOD

    print(D)
"}

