import sys

def solve() -> None:
    n, k, M = map(int, sys.stdin.readline().split())
    t = list(map(int, sys.stdin.readline().split()))

    # For each task, precompute time and points for solving 0..k subtasks
    times = [0] * (k + 1)
    points = [0] * (k + 1)

    # Prefix sums
    prefix = [0] * (k + 1)
    for i in range(k):
        prefix[i + 1] = prefix[i] + t[i]

    for x in range(k + 1):
        times[x] = prefix[x]
        points[x] = x

    # DP: dp[i][j] = minimum time to earn j points using first i tasks
    # Space optimization: use 2 arrays
    dp_prev = [float('inf')] * (k * n + 1)
    dp_prev[0] = 0

    for task in range(n):
        dp_curr = dp_prev[:]

        for curr_points in range(k * n + 1):
            if dp_prev[curr_points] == float('inf'):
                continue

            # Try all ways to solve this task
            for subtasks in range(k + 1):
                new_points = curr_points + points[subtasks]
                if new_points > k * n:
                    continue
                if dp_curr[new_points] > dp_prev[curr_points] + times[subtasks]:
                    dp_curr[new_points] = dp_prev[curr_points] + times[subtasks]

        dp_prev = dp_curr

    # Find the maximum points achievable within M minutes
    answer = 0
    for points in range(k * n + 1):
        if dp_prev[points] <= M:
            answer = points

    print(answer)

if __name__ == "__main__":
    solve()
