import sys

def solve() -> None:
    n, k, M = map(int, sys.stdin.readline().split())
    t = list(map(int, sys.stdin.readline().split()))

    # For each task, precompute time and points for solving 0..k subtasks
    times = [0] * (k + 1)
    points = [0] * (k + 1)

    # Prefix sums
    prefix = [0] * (k + 1)
    for i in range(k):
        prefix[i + 1] = prefix[i] + t[i]

    for x in range(k + 1):
        times[x] = prefix[x]
        points[x] = x

    # DP: dp[j] = maximum points we can earn with j minutes
    dp = [float('inf')] * (k * n + 1)
    dp[0] = 0

    for task in range(n):
        dp_new = dp[:]

        for j in range(k * n + 1):
            if dp[j] == float('inf'):
                continue

            for x in range(k + 1):
                if j + times[x] > k * n:
