k = int(k)
n = int(input())

# Create bonus matrix
bonus = [[0] * 26 for _ in range(26)]
for _ in range(n):
    x, y, c = input().split()
    bonus[ord(x)-65][ord(y)-65] = int(c)

# Convert string to indices
s_idx = [ord(c) - 65 for c in s]

# dp[i][j][t]: maximum euphony for first i characters, ending with character j, changed t times
INF = -10**9
dp = [[[INF] * (k+1) for _ in range(26)] for _ in range(len(s)+1)]

# Base case: first character
for j in range(26):
    if j == s_idx[0]:
        dp[1][j][0] = 0
    else:
        if k >= 1:
            dp[1][j][1] = 0
        else:
            dp[1][j][0] = INF

# Fill DP
for i in range(2, len(s)+1):
    for j in range(26):  # current character
        for t in range(k+1):
            if dp[i-1][j][t] == INF:
                continue

            # Keep current character (no change)
            dp[i][j][t] = max(dp[i][j][t], dp[i-1][j][t])

            # Change to character j (change needed)
            if t > 0:
                for prev in range(26):
                    new_val = dp[i-1][prev][t-1] + bonus[prev][j]
                    dp[i][j][t] = max(dp[i][j][t], new_val)

# Find maximum euphony
max_euphony = INF
for j in range(26):
    for t in range(k+1):
        max_euphony = max(max_euphony, dp[len(s)][j][t])

print(max_euphony)
