def can_be_printed(s: str, t: str) -> bool:
    if len(t) < len(s):
        return False

    # Map each character in s to the range of indices in t that it represents
    char_to_indices = {}
    pos = 0

    for char in s:
        # Find the starting position of char in t
        while pos < len(t) and t[pos] != char:
            pos += 1

        if pos >= len(t):
            return False  # Missing character

        # Find the ending position of this run of char in t
        end = pos
        while end < len(t) and t[end] == char:
            end += 1

        # Map this character to its range in t
        char_to_indices[char] = (pos, end - 1)  # Using end-1 as the end index

        # Move position forward
        pos = end

    # Verify the mapping is consistent
    for char, indices in char_to_indices.items():
        start, end = indices
        # The character must be the same throughout the range
        if any(t[i] != char for i in range(start, end + 1)):
            return False

        # Check if the pattern is consistent across occurrences
        # For all other occurrences of this character, they should map to the same pattern
        for i in range(start, end + 1):
            if any(t[i] != char for i in range(start, end + 1)):
                return False

    # Check if the last character of t matches the last character of s
    if t[-1] != s[-1]:
        return False

    return True

n = int(input())
for _ in range(n):
    s = input().strip()
    t = input().strip()

    if can_be_printed(s, t):
        print("YES")
    else:
        print("NO")
