def solve(s):
    t = []
    n = len(s)

    # Keep the first character as is
    if n > 0:
        t.append(s[0])

    for i in range(1, n):
        # If we haven't seen a 0 yet and the current character is 1,
        # change it to 0 to maintain balance
        if len(t) > 0 and t[-1] == '0' and s[i] == '1':
            t.append('0')
        else:
            # If we've seen a 0 and the current character is 0,
            # change it to 1 to maintain balance
            if len(t) > 0 and t[-1] == '1' and s[i] == '0':
                t.append('1')
            else:
                # Otherwise, keep it as is
                t.append(s[i])

    return ''.join(t)

