    b = list(map(int, input().split()))

    # Count occurrences of each color in Bob's guess
    color_count = {}
    for color in b:
        color_count[color] = color_count.get(color, 0) + 1

    # Check validity
    if x > y:
        print("NO")
        continue
    if y > (n + 1):
        print("NO")
        continue
    if x > n:
        print("NO")
        continue
    if x + (y - x) > n:
        print("NO")
        continue

    # We need exactly x positions where a_i == b_i
    # We need y colors total that are present in both
    # For the remaining n - y positions, we need colors not in Bob's guess

    # Create result array
    result = [0] * n

    # Place exact matches
    for i in range(n):
        if x > 0 and b[i] in color_count:
            result[i] = b[i]
            x -= 1

    # Place partial matches (different positions but same colors)
    for i in range(n):
        if y > 0 and b[i] in color_count and b[i] not in result:
            result[i] = b[i]
            y -= 1

    # Place non-matching colors (colors not in Bob's guess)
    # We need (n - y) such colors, using colors from 1 to n+1 that are missing
    # Since y <= n, we can always find enough colors

    # Find which colors are not in Bob's guess
    has_color = set(b)
    missing_colors = []
    for i in range(1, n + 2):
        if i not in has_color:
            missing_colors.append(i)

    # Place remaining colors
    for i in range(n):
        if result[i] == 0:
            result[i] = missing_colors.pop(0)

    print("YES")
    print(" ".join(map(str, result)))
