import sys

k = int(input())

# Dictionary to store: key=sum_value, value=set of sequence indices that can reach this sum
possible_sums = {}

# Dictionary to store sequence data
sequences = []

for i in range(k):
    n = int(input())
    a = list(map(int, input().split()))
    total = sum(a)

    # Compute possible sums after removing one element
    sums = set()
    for idx, val in enumerate(a):
        sums.add(total - val)

    sequences.append((total, a))

    # Update possible_sums dictionary
    for s in sums:
        if s not in possible_sums:
            possible_sums[s] = set()
        possible_sums[s].add(i + 1)  # Store 1-indexed sequence indices

# Debug: Print all possible sums and the indices that can reach them
print("Debug info:", file=sys.stderr)
for s, indices in possible_sums.items():
    print(f"Sum {s} can be reached by sequences: {indices}", file=sys.stderr)

# Find a sum that at least two sequences can reach
