    if len(indices) >= 2:
        # Try all pairs of sequences
        seqs = list(indices)
        for seq1 in range(len(seqs)):
            for seq2 in range(len(seqs)):
                if seq1 != seq2:
                    # Find valid elements for seq1 and seq2
                    idx1 = -1
                    idx2 = -1
                    for i1, val1 in enumerate(sequences[seqs[seq1] - 1][1]):
                        if sequences[seqs[seq1] - 1][0] - val1 == s:
                            idx1 = i1 + 1
                            break

                    for i2, val2 in enumerate(sequences[seqs[seq2] - 1][1]):
                        if sequences[seqs[seq2] - 1][0] - val2 == s:
                            idx2 = i2 + 1
                            break

                    # If we found valid indices, return
                    if idx1 != -1 and idx2 != -1:
                        print("YES")
                        print(seqs[seq1], idx1)
                        print(seqs[seq2], idx2)
                        found = True
                        sys.exit()

if not found:
    print("NO")
