def is_primitive(k, coeffs):
    """Check if the polynomial with degree k and given coeffs is primitive"""

    # Convert coeffs to a list (c_k, c_{k-1}, ..., c_1)
    # where an = c_1*an-1 + c_2*an-2 + ... + c_k*an-k
    coeffs = coeffs[::-1]

    # Check irreducible
    if not is_irreducible(k, coeffs):
        return False

    # Check order is exactly 2^k - 1
    order = 2**k - 1

    # Check x^order ≡ 1 (mod f(x))
    if not power_mod(2, order, coeffs):
        return False

    # Check for proper divisors d of order
    for d in get_proper_divisors(order):
        if power_mod(2, d, coeffs):
