import sys
from functools import lru_cache

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    r = int(data[0])
    s = int(data[1])
    p = int(data[2])

    @lru_cache(maxsize=None)
    def f(r, s, p):
        if s == 0 and p == 0:
            return 1.0  # only papers remain? No: r > 0, s == 0, p == 0 => only rocks remain => papers cannot survive => f = 0
        # Correction: if r > 0, s == 0, p == 0 => only rocks remain => papers cannot survive => f = 0
        # So we need: if r > 0 and s == 0 and p == 0: f = 0
        # We can check: if r > 0: return 0 if s == 0 and p == 0
        if r > 0 and s == 0 and p == 0:
            return 0.0
        if r == 0 and s > 0 and p == 0:
            return 0.0
        if r == 0 and s == 0 and p > 0:
            return 1.0
        # else
        total = r * s + s * p + p * r
        if total == 0:
            return 0.0
        return (r * s / total) * f(r, s - 1, p) + (s * p / total) * f(r, s, p - 1) + (p * r / total) * f(r - 1, s, p)

    prob_papers = f(r, s, p)
    prob_scissors = f(s, p, r)
    prob_rocks = f(r, p, s)

    print(f"{prob_rocks:.15f} {prob_scissors:.15f} {prob_papers:.15f}")

if __name__ == "__main__":
