    # Find missing numbers (numbers that are not in the array)
    missing = []
    for i in range(1, n + 1):
        if i not in permutation:
            missing.append(i)

    # Find positions with -1
    unknown_positions = [i for i in range(n) if permutation[i] == -1]

    # For each missing number, find which positions it can go to
    valid_positions = [[] for _ in range(len(missing))]
    for i, num in enumerate(missing):
        for pos in unknown_positions:
            # The number num can go to position pos if:
            # - pos is one of the unknown positions
            # - num can't go to its own position (num is the value, pos is the index)
            if pos != num:
                valid_positions[i].append(pos)

    # We need to count the number of ways to assign the missing numbers to unknown positions
    # This is similar to counting derangements with specific restrictions
    # I'll use dynamic programming for this

    # dp[mask][last] = number of ways to assign the first 'last' positions with mask
    # mask: bitmask representing which missing numbers have been used
    # last: which position we just assigned (0-indexed)
    # dp[mask][last] = ways to reach this state

    dp = {}
    dp[0] = {None: 1}

    for i, pos in enumerate(unknown_positions):
        new_dp = {}
        for mask in dp:
            for last in dp[mask]:
                ways = dp[mask][last]
                if ways == 0:
                    continue

                # Try assigning each missing number to this position
                for j in range(len(missing)):
                    if mask & (1 << j):
                        continue  # Already used this number
                    if pos not in valid_positions[j]:
                        continue  # Not a valid assignment

                    new_mask = mask | (1 << j)
                    if new_mask not in new_dp:
                        new_dp[new_mask] = {}
                    new_dp[new_mask][pos] = (new_dp[new_mask].get(pos, 0) + ways) % MOD
        dp = new_dp

    # Sum all ways to assign all missing numbers to all unknown positions
    total = 0
    for mask in dp:
        for pos in dp[mask]:
            total = (total + dp[mask][pos]) % MOD

    return total

