# Generate all possible combinations of three values
# This includes all ways to pick values from the array
# We need to consider combinations like (1, 1, 2) and (1, 2, 3)

min_product = float('inf')
min_triples = []

# Try all combinations of values, considering duplicates
# This is equivalent to finding the minimum product of any three elements
# by trying all combinations of values with their multiplicities
for v1 in values:
    for v2 in values:
        if v2 < v1:
            continue
        for v3 in values:
            if v3 < v2:
                continue
            product = v1 * v2 * v3
            if product < min_product:
                min_product = product
                min_triples = [(v1, v2, v3)]
            elif product == min_product:
                min_triples.append((v1, v2, v3))

# Now count the number of actual triples that achieve this minimum product
result = 0

for triple in min_triples:
    v1 = triple[0]
    v2 = triple[1]
    v3 = triple[2]

    # Count how many times each value appears
    count_v1 = counts[v1]
    count_v2 = counts[v2]
    count_v3 = counts[v3]

    # Case: all distinct
    if v1 != v2 and v2 != v3:
        result += count_v1 * count_v2 * count_v3
    # Case: two of one value, one of another
    elif v1 == v2 and v2 != v3:
        result += (count_v1 * (count_v1 - 1) // 2) * count_v3
