import sys
import math
from math import gcd

def are_friends(a, b):
    g = gcd(a, b)
    g_squared = g * g

    # Check the triangle conditions for sides g, a/g, b/g
    # Multiplying by g gives:
    # g^2 + a > b
    # g^2 + b > a
    # a + b > g^2

    return (g_squared + a > b) and (g_squared + b > a) and (a + b > g_squared)

def is_lonely(n):
    for i in range(1, n + 1):
        is_lonely_flag = True
        for j in range(1, n + 1):
            if i == j:
                continue
            if are_friends(i, j):
                is_lonely_flag = False
                break
        if is_lonely_flag:
            return i
    return -1

# Precompute the answer for all numbers up to max_n
max_n = 10**6
answers = [0] * (max_n + 1)
answers[1] = 1

for i in range(2, max_n + 1):
    is_lonely = True
    for j in range(1, i):
        if are_friends(i, j):
            is_lonely = False
            break
    if is_lonely:
        answers[i] = answers[i - 1] + 1
    else:
        answers[i] = answers[i - 1]

# Read input and output
