def solve():
    T = int(input())
    results = []

    for _ in range(T):
        N = int(input())

        # Let me think about it as a minimax problem
        # Mr. Chanek's turn: he tries to maximize his coins
        # Opponent's turn: they try to minimize Mr. Chanek's coins

        memo = {}

        def get_coins(n, is_my_turn):
            if n == 0:
                return 0

            if is_my_turn:
                # Mr. Chanek's turn: maximize his coins
                # He can take 1 coin, then opponent takes from n-1
                take1 = 1 + get_coins(n - 1, False)

                # He can take half if n is even
                if n % 2 == 0:
                    take_half = (n // 2) + get_coins(n // 2, False)
                    take1 = max(take1, take_half)

                return take1
            else:
                # Opponent's turn: minimize Mr. Chanek's coins
                # They can take 1 coin, then Mr. Chanek takes from n-1
                take1 = get_coins(n - 1, True)

                # They can take half if n is even
