        # If N is exactly a power of 2, Mr. Chanek gets N/2
        if power == N:
            results.append(power // 2)
        else:
            # Otherwise, Mr. Chanek gets (N - power) // 2 + power // 2
            results.append((N - power) // 2 + power // 2)

