import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    weights = list(map(int, data[1:2*n+1]))
    weights.sort()

    min_instability = float('inf')

    # Try all possible pairs to be in single kayaks
    for i in range(len(weights)):
        for j in range(i+1, len(weights)):
            # i and j are singles, their instability is 0
            # Remaining people: all except i and j
            # Pair adjacent remaining people
            instability = 0
            remaining = []

            for k in range(len(weights)):
                if k != i and k != j:
                    remaining.append(weights[k])

            # Now pair adjacent in remaining
            for p in range(0, len(remaining), 2):
                instability += abs(remaining[p] - remaining[p+1])

            min_instability = min(min_instability, instability)

    print(min_instability)

if __name__ == "__main__":
    solve()
"}

